#!/usr/bin/env python3
"""Apply script: fix false-positive labeled-row match on a real Cigna SmartCare TOB.

Run from the HealthCross repo root: python3 apply_cigna_smartcare_false_positive_fix.py
"""
import base64, hashlib, os, sys

MARKER = "CIGNA_SMARTCARE_FALSE_POSITIVE_FIX_2026_08_05"

FILES = [
    {
        'path': 'app/ingestion/labeled_row_benefits_pdf.py',
        'sha256': '56f844eb0d24384bc7056516419be3ba848624234174dbf864a0d0702f0fd00b',
        'size': 13813,
        'b64': '',
    },
    {
        'path': 'tests/test_ingestion_labeled_row_benefits_pdf.py',
        'sha256': 'a2162d4382ca375957adccde58662fafad590f504aebdadf8f06eefcda6bb5d5',
        'size': 5108,
        'b64': '',
    },
    {
        'path': 'tests/test_api_benefits_labeled_row.py',
        'sha256': 'f2b951b77a7bace8e01d08661a77ab23f10926e929903cc95193c86b2d80fb6f',
        'size': 3836,
        'b64': '',
    },
    {
        'path': 'tests/fixtures/Table_of_Benefits_Cigna_SmartCare_Annexure1.pdf',
        'sha256': '3203d49ece48737a9e54a05c796ea75e21eba16c58f35489258dcf63a1f4051d',
        'size': 500723,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 480 passed)")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
